"use strict";(self.webpackChunkdocs_site=self.webpackChunkdocs_site||[]).push([["1924"],{5226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Stage A","banner":null,"badge":true,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"overviewSidebar":[{"type":"link","href":"/","label":"Overview","docId":"overview/index","unlisted":false},{"type":"link","href":"/overview/plan","label":"Plan","docId":"overview/plan","unlisted":false}],"dataSidebar":[{"type":"link","href":"/data/","label":"Overview","docId":"data/index","unlisted":false},{"type":"category","label":"Platform schema","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/data/platform/organizations","label":"Organizations","docId":"data/platform/organizations","unlisted":false},{"type":"link","href":"/data/platform/users-and-membership","label":"Users & membership","docId":"data/platform/users-and-membership","unlisted":false},{"type":"link","href":"/data/platform/user-invitations","label":"User invitations","docId":"data/platform/user-invitations","unlisted":false}],"href":"/data/platform/"},{"type":"category","label":"Org schema","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/data/org/organization-settings","label":"Organization settings","docId":"data/org/organization-settings","unlisted":false},{"type":"link","href":"/data/org/customers","label":"Customers","docId":"data/org/customers","unlisted":false},{"type":"link","href":"/data/org/vendors","label":"Vendors","docId":"data/org/vendors","unlisted":false},{"type":"link","href":"/data/org/products","label":"Products","docId":"data/org/products","unlisted":false},{"type":"link","href":"/data/org/materials","label":"Materials","docId":"data/org/materials","unlisted":false},{"type":"link","href":"/data/org/locations","label":"Locations","docId":"data/org/locations","unlisted":false},{"type":"link","href":"/data/org/order-channels","label":"Order channels","docId":"data/org/order-channels","unlisted":false},{"type":"link","href":"/data/org/contacts","label":"Contacts","docId":"data/org/contacts","unlisted":false},{"type":"link","href":"/data/org/documents","label":"Documents","docId":"data/org/documents","unlisted":false},{"type":"link","href":"/data/org/bom","label":"Bill of materials","docId":"data/org/bom","unlisted":false},{"type":"link","href":"/data/org/purchase-orders","label":"Purchase orders","docId":"data/org/purchase-orders","unlisted":false},{"type":"link","href":"/data/org/work-orders","label":"Work orders","docId":"data/org/work-orders","unlisted":false},{"type":"link","href":"/data/org/sales-orders","label":"Sales orders","docId":"data/org/sales-orders","unlisted":false},{"type":"link","href":"/data/org/materials-inventory-ledger","label":"Materials inventory ledger","docId":"data/org/materials-inventory-ledger","unlisted":false},{"type":"link","href":"/data/org/finished-goods-inventory-ledger","label":"Finished goods inventory ledger","docId":"data/org/finished-goods-inventory-ledger","unlisted":false}],"href":"/data/org/"}],"componentsSidebar":[{"type":"link","href":"/components/","label":"Layer 2 \u2014 Components","docId":"components/index","unlisted":false}],"businessLogicSidebar":[{"type":"link","href":"/business-logic/","label":"Layer 3 \u2014 Business Logic","docId":"business-logic/index","unlisted":false}],"apiSidebar":[{"type":"link","href":"/api/","label":"Overview","docId":"api/index","unlisted":false},{"type":"category","label":"User Actions","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/api/user-actions/platform","label":"Platform","docId":"api/user-actions/platform","unlisted":false},{"type":"link","href":"/api/user-actions/purchase-orders","label":"Purchase Orders","docId":"api/user-actions/purchase-orders","unlisted":false},{"type":"link","href":"/api/user-actions/work-orders","label":"Work Orders","docId":"api/user-actions/work-orders","unlisted":false},{"type":"link","href":"/api/user-actions/sales-orders","label":"Sales Orders","docId":"api/user-actions/sales-orders","unlisted":false},{"type":"link","href":"/api/user-actions/materials-inventory","label":"Materials Inventory","docId":"api/user-actions/materials-inventory","unlisted":false},{"type":"link","href":"/api/user-actions/finished-goods-inventory","label":"Finished Goods Inventory","docId":"api/user-actions/finished-goods-inventory","unlisted":false},{"type":"link","href":"/api/user-actions/customers","label":"Customers","docId":"api/user-actions/customers","unlisted":false},{"type":"link","href":"/api/user-actions/products","label":"Products","docId":"api/user-actions/products","unlisted":false},{"type":"link","href":"/api/user-actions/bom","label":"Bill of Materials","docId":"api/user-actions/bom","unlisted":false},{"type":"link","href":"/api/user-actions/vendors","label":"Vendors","docId":"api/user-actions/vendors","unlisted":false},{"type":"link","href":"/api/user-actions/materials","label":"Materials","docId":"api/user-actions/materials","unlisted":false},{"type":"link","href":"/api/user-actions/locations","label":"Locations","docId":"api/user-actions/locations","unlisted":false},{"type":"link","href":"/api/user-actions/contacts","label":"Contacts","docId":"api/user-actions/contacts","unlisted":false}],"href":"/api/user-actions/"}],"clientsSidebar":[{"type":"link","href":"/clients/","label":"Layer 5 \u2014 Clients","docId":"clients/index","unlisted":false}]},"docs":{"api/index":{"id":"api/index","title":"Overview","description":"A single public API service. Versioned contract. Every user action from the frontend \u2014 write or read \u2014 maps to an endpoint here. Each endpoint calls into one or more L3 workflows; no endpoint reaches Layer 2 directly.","sidebar":"apiSidebar"},"api/user-actions/bom":{"id":"api/user-actions/bom","title":"Bill of Materials","description":"Covers BOMs \u2014 the composition that links input materials and/or input SKUs (with quantities) to an output SKU. A BOM is a recipe: one entry per output SKU. Read by cost-cascade and WO workflows; written from the BOM editor.","sidebar":"apiSidebar"},"api/user-actions/contacts":{"id":"api/user-actions/contacts","title":"Contacts","description":"Covers the shared contacts pool \u2014 people (with optional email/phone methods) that can be linked to customers, vendors, or other entities. The same contact can be reused across multiple entities, each link carrying its own role and notes.","sidebar":"apiSidebar"},"api/user-actions/customers":{"id":"api/user-actions/customers","title":"Customers","description":"Covers customers, the master-data tables that classify them (customer types, customer segments), and brokers (reusable broker entities used on customers and SOs).","sidebar":"apiSidebar"},"api/user-actions/finished-goods-inventory":{"id":"api/user-actions/finished-goods-inventory","title":"Finished Goods Inventory","description":"Covers the finished-goods inventory ledger (every movement of finished SKUs in/out/between locations) and the derived summary view (current stock by SKU \xd7 location). Most ledger entries are written automatically by SO operations (DEMAND / ALLOCATE / CONSUME) and WO operations (RECEIVE on completion); direct ledger writes are used for manual transfers, adjustments, and disposals.","sidebar":"apiSidebar"},"api/user-actions/index":{"id":"api/user-actions/index","title":"User Actions","description":"This is the catalog of every action a user can take in the platform today \u2014 both writes (create, update, delete) and reads (lists, lookups, detail views). It\'s the source of truth that everything downstream in the design phase builds on:","sidebar":"apiSidebar"},"api/user-actions/locations":{"id":"api/user-actions/locations","title":"Locations","description":"Covers fulfillment locations \u2014 warehouses / fulfillment centers / work sites. The same entity is reused as PO ship-to, WO work site, SO fulfillment location, and inventory bin across materials and finished goods.","sidebar":"apiSidebar"},"api/user-actions/materials":{"id":"api/user-actions/materials","title":"Materials","description":"Covers materials (raw inputs consumed by work orders or purchased on materials POs) and their type table.","sidebar":"apiSidebar"},"api/user-actions/materials-inventory":{"id":"api/user-actions/materials-inventory","title":"Materials Inventory","description":"Covers the materials inventory ledger (every movement of raw materials in/out/between locations) and the derived summary view (current stock by material \xd7 location). Most ledger entries are written automatically by PO receipts (RECEIVE) and WO operations (CONSUME); direct ledger writes are used for manual transfers, adjustments, and disposals.","sidebar":"apiSidebar"},"api/user-actions/platform":{"id":"api/user-actions/platform","title":"Platform","description":"Covers authentication, organizations, organization users, invitations, and the Home page bundle. The shared contacts pool is documented separately in Contacts.","sidebar":"apiSidebar"},"api/user-actions/products":{"id":"api/user-actions/products","title":"Products","description":"Covers SKUs (finished goods) and their type table. Materials and BOMs each have their own page; see Materials and Bill of Materials.","sidebar":"apiSidebar"},"api/user-actions/purchase-orders":{"id":"api/user-actions/purchase-orders","title":"Purchase Orders","description":"Covers purchase orders (PO), PO items, PO receipts, and PO status types. POs target either materials (raw inputs) or finished goods (resale), set on creation. Receipts drive the materials or finished-goods inventory ledger.","sidebar":"apiSidebar"},"api/user-actions/sales-orders":{"id":"api/user-actions/sales-orders","title":"Sales Orders","description":"Covers sales orders (SO), SO items, SO timeline notes, SO documents, and the SO-side master data (order channels, order status types, fulfillment status types). SO operations also drive the finished-goods inventory ledger (DEMAND / ALLOCATE / CONSUME events).","sidebar":"apiSidebar"},"api/user-actions/vendors":{"id":"api/user-actions/vendors","title":"Vendors","description":"Covers vendors \u2014 master data for the suppliers that POs are placed against. Vendor contacts are managed through the shared contacts pool (see Contacts).","sidebar":"apiSidebar"},"api/user-actions/work-orders":{"id":"api/user-actions/work-orders","title":"Work Orders","description":"Covers work orders (WO), WO items, WO receipts, and WO status types. WOs convert materials into finished goods at a work site (a fulfillment location). Operations drive both the materials inventory ledger (consumption) and the finished-goods inventory ledger (production).","sidebar":"apiSidebar"},"business-logic/index":{"id":"business-logic/index","title":"Layer 3 \u2014 Business Logic","description":"A single template \u2014 Anthem \u2014 runs the show. Every workflow, every constraint, every validation behind a user action lives here. J&B and the variant/extension model belong to later stages.","sidebar":"businessLogicSidebar"},"clients/index":{"id":"clients/index","title":"Layer 5 \u2014 Clients","description":"The web app is the only client in Stage A. It becomes a thin client \u2014 local logic (aggregations, derived state, N+1 fetches) moves into the backend behind L4 endpoints. No new client surfaces (mobile, desktop, CLI, AI agents, partner integrations) in this stage.","sidebar":"clientsSidebar"},"components/index":{"id":"components/index","title":"Layer 2 \u2014 Components","description":"Stateless modules \u2014 one per domain \u2014 running in-process inside the single backend service. Not microservices yet; the contract is what matters now, not the deployment shape.","sidebar":"componentsSidebar"},"data/index":{"id":"data/index","title":"Overview","description":"Single Postgres instance. One shared database. Two logical schemas inside that database mark the boundary between platform data (the tenant catalog and identity layer) and org data (everything tenant-scoped). Tenant rows still carry org_id for shared-DB isolation.","sidebar":"dataSidebar"},"data/org/bom":{"id":"data/org/bom","title":"Bill of materials","description":"The composition that links input materials and/or input SKUs (with quantities) to an output SKU. One row per (output SKU \xd7 input). Polymorphic on the input side because materials and SKUs are kept separate.","sidebar":"dataSidebar"},"data/org/contacts":{"id":"data/org/contacts","title":"Contacts","description":"Org-private pool of people, with optional email/phone methods, linkable to any entity in the org (customer, vendor, etc.). One contact can be linked to multiple entities, each link carrying its own role and notes. Reason: contacts stay org-scoped rather than promoted to a shared platform pool.","sidebar":"dataSidebar"},"data/org/customers":{"id":"data/org/customers","title":"Customers","description":"Sales-side parties. Carries the rich model: classification (type + segment), default broker, hierarchy (parent customer), country, QBO sync. Auxiliary tables in this cluster (customertypes, customersegments, brokers) only exist for customers \u2014 they\'re not shared with vendors, which carry a deliberately flatter shape.","sidebar":"dataSidebar"},"data/org/documents":{"id":"data/org/documents","title":"Documents","description":"Polymorphic file attachments. One row per uploaded file, linked to any entity in the org (sales order, purchase order, work order, \u2026). Same shape pattern as org.entity_contacts \u2014 one table covers every entity kind.","sidebar":"dataSidebar"},"data/org/finished-goods-inventory-ledger":{"id":"data/org/finished-goods-inventory-ledger","title":"Finished goods inventory ledger","description":"Append-only event log for finished-goods movement. Same shape as the materials ledger, anchored on skuid instead of materialid. Summary views are derived.","sidebar":"dataSidebar"},"data/org/index":{"id":"data/org/index","title":"Overview","description":"Tenant-scoped tables. Every row carries orgid UUID NOT NULL REFERENCES platform.organizations(id) for shared-DB isolation. Per-tenant uniqueness is enforced via composite constraints (UNIQUE(orgid, name), UNIQUE(org_id, code), etc.).","sidebar":"dataSidebar"},"data/org/locations":{"id":"data/org/locations","title":"Locations","description":"Renamed from fulfillment_locations. Used as PO ship-to, WO work site, SO fulfillment location, and inventory stock bin.","sidebar":"dataSidebar"},"data/org/materials":{"id":"data/org/materials","title":"Materials","description":"Raw inputs purchased on materials POs and consumed by work orders to produce SKUs.","sidebar":"dataSidebar"},"data/org/materials-inventory-ledger":{"id":"data/org/materials-inventory-ledger","title":"Materials inventory ledger","description":"Append-only event log for materials movement. The summary view (\\"on-hand by material \xd7 location\\") is derived from this table; it isn\'t stored.","sidebar":"dataSidebar"},"data/org/order-channels":{"id":"data/org/order-channels","title":"Order channels","description":"Sales channel classification \u2014 Direct, Distributor, Marketplace, etc. Required on every sales order. Per-org configurable.","sidebar":"dataSidebar"},"data/org/organization-settings":{"id":"data/org/organization-settings","title":"Organization settings","description":"Presentation-layer data for the org \u2014 legal name, address, logo, contact info. Singleton: one row per org, keyed by org_id.","sidebar":"dataSidebar"},"data/org/products":{"id":"data/org/products","title":"Products","description":"Finished goods. Produced by work orders, sold via sales orders, and (since #330) sometimes purchased directly via finished-goods POs.","sidebar":"dataSidebar"},"data/org/purchase-orders":{"id":"data/org/purchase-orders","title":"Purchase orders","description":"Header + line items + receipts. The header carries targettype choosing whether the line items reference materials or SKUs. Status is an org.postatus ENUM stored directly on the row.","sidebar":"dataSidebar"},"data/org/sales-orders":{"id":"data/org/sales-orders","title":"Sales orders","description":"Header + line items + timeline notes + documents. Two status fields: orderstatus (org.orderstatus ENUM) and fulfillmentstatus (org.fulfillmentstatus ENUM), both stored directly on the row.","sidebar":"dataSidebar"},"data/org/vendors":{"id":"data/org/vendors","title":"Vendors","description":"Purchase-side parties.","sidebar":"dataSidebar"},"data/org/work-orders":{"id":"data/org/work-orders","title":"Work orders","description":"Header + output line items + recipe snapshot + receipts. WOs convert materials into finished goods at a work site (a org.locations row). The recipe (which inputs are needed for each output line) is snapshotted from bom_items at the time the WO line is created \u2014 see workorderinputs below. Status is an org.wo_status ENUM stored directly on the row.","sidebar":"dataSidebar"},"data/platform/index":{"id":"data/platform/index","title":"Overview","description":"Tenant catalog, identity, and invitations. These tables exist exactly once in the database and survive unchanged into a future per-tenant physical split \u2014 they\'re what every tenant needs to know about every other tenant, plus the identity layer that lets one human belong to many tenants.","sidebar":"dataSidebar"},"data/platform/organizations":{"id":"data/platform/organizations","title":"Organizations","description":"Tenant catalog row. Holds identity only \u2014 presentation fields (legal name, address, logo, contact info) live in org.organization_settings.","sidebar":"dataSidebar"},"data/platform/user-invitations":{"id":"data/platform/user-invitations","title":"User invitations","description":"Invitations issued by an org to an email.","sidebar":"dataSidebar"},"data/platform/users-and-membership":{"id":"data/platform/users-and-membership","title":"Users & membership","description":"Identity lives on platform.users; per-tenant membership and role live on platform.organization_users.","sidebar":"dataSidebar"},"overview/index":{"id":"overview/index","title":"Overview","description":"Stage A is the first step on the path toward the architecture described in the Full Scale version of these docs (use the version dropdown in the navbar to switch). It reshapes the current backend into a clear stack \u2014 domain components, a business logic layer, and a real public API \u2014 with the frontend reduced to a thin client. The database stays as it is. The point isn\'t features; it\'s groundwork \u2014 putting the codebase in a shape where later stages can each focus on one specific piece of the destination instead of fighting the foundation.","sidebar":"overviewSidebar"},"overview/plan":{"id":"overview/plan","title":"Plan","description":"All docs deliverables below live in this docs site, organized by layer.","sidebar":"overviewSidebar"}}}}')}}]);